// Config plugin: wires android/app/build.gradle's `release` build type to a
// real signing config instead of the RN/Expo template's default (which
// silently signs release builds with the debug keystore - fine for local
// testing, not for Play Store).
//
// android/ isn't committed (see NATIVE_APP.md - this repo uses Continuous
// Native Generation, regenerated by `expo prebuild` from app.json + these
// plugins), so this has to be a build.gradle *mod*, not a hand edit.
//
// The generated Gradle reads the actual key material from environment
// variables at *build* time (via System.getenv), not from anything baked in
// at prebuild time - see native/NATIVE_APP.md for the required
// ANDROID_UPLOAD_* env vars / GitHub secrets. When they're unset (e.g. a
// local dev build), it transparently falls back to the debug keystore,
// exactly like the unmodified template does today.
const { withAppBuildGradle } = require("@expo/config-plugins");

const RELEASE_SIGNING_CONFIG = `        release {
            if (System.getenv("ANDROID_UPLOAD_STORE_FILE")) {
                storeFile file(System.getenv("ANDROID_UPLOAD_STORE_FILE"))
                storePassword System.getenv("ANDROID_UPLOAD_STORE_PASSWORD")
                keyAlias System.getenv("ANDROID_UPLOAD_KEY_ALIAS")
                keyPassword System.getenv("ANDROID_UPLOAD_KEY_PASSWORD")
            } else {
                storeFile file('debug.keystore')
                storePassword 'android'
                keyAlias 'androiddebugkey'
                keyPassword 'android'
            }
        }
`;

const SIGNING_CONFIGS_ANCHOR = "signingConfigs {\n";

const RELEASE_BUILD_TYPE_COMMENT =
  "            // Caution! In production, you need to generate your own keystore file.\n" +
  "            // see https://reactnative.dev/docs/signed-apk-android.\n" +
  "            signingConfig signingConfigs.debug\n";

const RELEASE_BUILD_TYPE_REPLACEMENT =
  "            // Signed with the ANDROID_UPLOAD_* keystore when present (see\n" +
  "            // native/NATIVE_APP.md); falls back to the debug keystore otherwise.\n" +
  "            signingConfig signingConfigs.release\n";

function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    const contents = config.modResults.contents;

    if (!contents.includes(SIGNING_CONFIGS_ANCHOR)) {
      throw new Error(
        "withAndroidReleaseSigning: couldn't find `signingConfigs {` in android/app/build.gradle - " +
          "the generated template may have changed; update plugins/withAndroidReleaseSigning.js.",
      );
    }
    if (!contents.includes(RELEASE_BUILD_TYPE_COMMENT)) {
      throw new Error(
        "withAndroidReleaseSigning: couldn't find the expected `release {}` build type block in " +
          "android/app/build.gradle - the generated template may have changed; update " +
          "plugins/withAndroidReleaseSigning.js.",
      );
    }

    config.modResults.contents = contents
      .replace(SIGNING_CONFIGS_ANCHOR, SIGNING_CONFIGS_ANCHOR + RELEASE_SIGNING_CONFIG)
      .replace(RELEASE_BUILD_TYPE_COMMENT, RELEASE_BUILD_TYPE_REPLACEMENT);

    return config;
  });
}

module.exports = withAndroidReleaseSigning;
